import React from 'react';
import ComparisonCharts from './ComparisonCharts';

const SimulationDashboard = ({ results }) => {

    if (!results) {
        return (
            <div>
                <h1>Simulation Dashboard</h1>
                <p>No simulation results yet. Please run the simulation first.</p>
            </div>
        );
    }

    return (
        <div>
            <h1>Simulation Dashboard</h1>

            <h2>Simulation Results</h2>

            <p>
                <strong>Average Lifetime (steps):</strong> {results.average_lifetime}
            </p>

            <p>
                <strong>Total Energy (units):</strong> {results.total_energy}
            </p>

            <ComparisonCharts results={results} />

        </div>
    );
};

export default SimulationDashboard;
